import yaml



def change_config_path(yaml_path, new_cohort_dir):

    with open(yaml_path, 'r') as f:
        config = yaml.safe_load(f)
    config['cohort_dir'] = new_cohort_dir
    with open(yaml_path, 'w') as f:
        yaml.dump(config, f)

